

import React, { useEffect } from "react";
import { useRef } from "react";
import gsap from "gsap";

function Page() {
  const boxRef = useRef(null);

  useEffect(()=>{
    gsap.fromTo(
      boxRef.current, {
        opacity: 0,
        scale: 0.3,

      }
    )
  }, []);


  return (
    <section className="bg-[#11274a] min-h-screen flex items-center justify-center">
      <div className="w-51.25 h-51.25 bg-[linear-gradient(135deg,#1dd1a1,#54a0ff)] rounded-xl shadow-xl opacity-100">
        
      </div>
    </section>
  );
}

export default Page;